/* @lc app=leetcode id=2054 lang=kotlin */
class Solution { fun maxTwoEvents(events: Array<IntArray>): Int = events.sortedBy { it[1] }.let { sorted -> IntArray(sorted.size).let { prefixMax -> IntArray(1).let { cur -> sorted.forEachIndexed { i, e -> maxOf(cur[0], e[2]).also { cur[0] = it }.run { prefixMax[i] = cur[0] } } }.run { sorted.indices.maxOf { i -> sorted[i][2] + intArrayOf(0, i - 1, -1).let { v -> generateSequence(0) { it }.takeWhile { v[0] <= v[1] }.forEach { ((v[0] + v[1]) / 2).let { m -> if (sorted[m][1] < sorted[i][0]) m.also { v[2] = it }.run { v[0] = it + 1 } else (m - 1).also { v[1] = it } } }.run { if (v[2] != -1) prefixMax[v[2]] else 0 } } } } } }